// HOME NAV, WOW.JS & HERO SECTION STYLES START
// Initialize WOW.js on launch
document.addEventListener("DOMContentLoaded", function () {
  new WOW({
    boxClass: "wow",
    animateClass: "animate__animated",
    offset: 50,
    mobile: true,
    live: true,
  }).init();

  // Smooth section scrolling with sticky navbar height calculation
  const navLinks = document.querySelectorAll(".nav-scroll-link");
  const navBarElement = document.getElementById("mainNav");
  const navCollapse = document.getElementById("advisolNavContent");
  const mobileCloseBtn = document.getElementById("mobileNavCloseBtn");

  // Helper function to close the mobile menu
  const closeMobileMenu = () => {
    if (navCollapse && navCollapse.classList.contains("show")) {
      const bsCollapse =
        bootstrap.Collapse.getInstance(navCollapse) ||
        new bootstrap.Collapse(navCollapse, { toggle: false });
      if (bsCollapse) bsCollapse.hide();
    }
  };

  // Close button inside the opened mobile drawer
  if (mobileCloseBtn) {
    mobileCloseBtn.addEventListener("click", closeMobileMenu);
  }

  navLinks.forEach((link) => {
    link.addEventListener("click", function (e) {
      const targetId = this.getAttribute("href");

      if (targetId && targetId.startsWith("#")) {
        const targetElement = document.querySelector(targetId);
        if (targetElement) {
          e.preventDefault();

          // Close mobile navbar automatically if open
          closeMobileMenu();

          // Compute navbar height offset to avoid obscuring headers
          const navHeight = navBarElement.offsetHeight;
          const targetPosition =
            targetElement.getBoundingClientRect().top +
            window.pageYOffset -
            (navHeight - 10);

          window.scrollTo({
            top: targetPosition,
            behavior: "smooth",
          });
        }
      }
    });
  });
});

// Dynamic Navigation Scroll Background Changer
const nav = document.getElementById("mainNav");
window.addEventListener("scroll", () => {
  if (window.scrollY > 40) {
    nav.classList.add("scrolled");
  } else {
    nav.classList.remove("scrolled");
  }
});

// Subtle Interactive Mouse Parallax for Floating Elements
const heroVisual = document.getElementById("interactiveCanvas");
const parallaxItems = document.querySelectorAll(".parallax-element");

if (heroVisual && window.innerWidth > 992) {
  heroVisual.addEventListener("mousemove", (e) => {
    const rect = heroVisual.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width - 0.5;
    const y = (e.clientY - rect.top) / rect.height - 0.5;

    parallaxItems.forEach((item) => {
      const speed = parseFloat(item.getAttribute("data-speed")) || 10;
      const moveX = x * speed;
      const moveY = y * speed;
      item.style.transform = `translate3d(${moveX}px, ${moveY}px, 0)`;
    });
  });

  heroVisual.addEventListener("mouseleave", () => {
    parallaxItems.forEach((item) => {
      item.style.transform = `translate3d(0px, 0px, 0)`;
    });
  });
}
// HOME NAV, WOW.JS & HERO SECTION STYLES END

// HOME SECTION 1 START
document.addEventListener("DOMContentLoaded", function () {
  // 1. ANIMATED NUMBER COUNTERS
  const counters = document.querySelectorAll(".counter-ticker");
  let countersAnimated = false;

  const countUp = (el, target, duration = 1800) => {
    let startTimestamp = null;
    const step = (timestamp) => {
      if (!startTimestamp) startTimestamp = timestamp;
      const progress = Math.min((timestamp - startTimestamp) / duration, 1);
      // Ease-out expo math curve
      const currentVal = Math.floor(progress === 1 ? target : target * (1 - Math.pow(2, -10 * progress)));
      el.textContent = currentVal;
      if (progress < 1) {
        window.requestAnimationFrame(step);
      } else {
        el.textContent = target;
      }
    };
    window.requestAnimationFrame(step);
  };

  // 2. SKILL PROGRESS BARS TRIGGER
  const skillFills = document.querySelectorAll(".skill-fill");

  const animateSkillsAndCounters = (entries, observer) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        // Trigger counters once
        if (!countersAnimated) {
          counters.forEach((counter) => {
            const target = parseInt(counter.getAttribute("data-target"), 10);
            countUp(counter, target);
          });
          countersAnimated = true;
        }

        // Trigger progress bar fills
        skillFills.forEach((fill) => {
          const fillWidth = fill.getAttribute("data-width");
          fill.style.width = fillWidth;
        });

        observer.unobserve(entry.target);
      }
    });
  };

  const aboutObserver = new IntersectionObserver(animateSkillsAndCounters, {
    threshold: 0.25,
  });

  const aboutSection = document.getElementById("about");
  if (aboutSection) {
    aboutObserver.observe(aboutSection);
  }
});
// HOME SECTION 1 END

/* HOME SECTION 5 REVIEWS START  */
document.addEventListener("DOMContentLoaded", function () {
  const track = document.getElementById("testimonialTrack");
  const slides = document.querySelectorAll(".testimonial-slide");
  const prevBtn = document.getElementById("sliderPrev");
  const nextBtn = document.getElementById("sliderNext");
  const dotsContainer = document.getElementById("sliderDots");

  if (!track || slides.length === 0) return;

  let currentIndex = 0;
  let autoPlayInterval = null;

  // Determine how many slides are visible based on screen size
  const getVisibleSlides = () => {
    if (window.innerWidth < 650) return 1;
    if (window.innerWidth < 992) return 2;
    return 3;
  };

  const getMaxIndex = () => {
    return Math.max(0, slides.length - getVisibleSlides());
  };

  // Render Dots
  const createDots = () => {
    dotsContainer.innerHTML = "";
    const totalDots = getMaxIndex() + 1;
    for (let i = 0; i < totalDots; i++) {
      const dot = document.createElement("span");
      dot.classList.add("slider-dot");
      if (i === currentIndex) dot.classList.add("active");
      dot.addEventListener("click", () => {
        currentIndex = i;
        updateSlider();
      });
      dotsContainer.appendChild(dot);
    }
  };

  // Update slider position
  const updateSlider = () => {
    const slideWidthPercent = 100 / getVisibleSlides();
    track.style.transform = `translateX(-${currentIndex * slideWidthPercent}%)`;

    // Update active dot
    const dots = dotsContainer.querySelectorAll(".slider-dot");
    dots.forEach((dot, idx) => {
      dot.classList.toggle("active", idx === currentIndex);
    });
  };

  const nextSlide = () => {
    if (currentIndex < getMaxIndex()) {
      currentIndex++;
    } else {
      currentIndex = 0;
    }
    updateSlider();
  };

  const prevSlide = () => {
    if (currentIndex > 0) {
      currentIndex--;
    } else {
      currentIndex = getMaxIndex();
    }
    updateSlider();
  };

  nextBtn.addEventListener("click", nextSlide);
  prevBtn.addEventListener("click", prevSlide);

  // Auto-play every 5 seconds (pauses on hover)
  const startAutoPlay = () => {
    autoPlayInterval = setInterval(nextSlide, 5000);
  };

  const stopAutoPlay = () => {
    clearInterval(autoPlayInterval);
  };

  track.addEventListener("mouseenter", stopAutoPlay);
  track.addEventListener("mouseleave", startAutoPlay);

  // Touch Swipe for Mobile
  let startX = 0;
  track.addEventListener("touchstart", (e) => {
    startX = e.touches[0].clientX;
    stopAutoPlay();
  }, { passive: true });

  track.addEventListener("touchend", (e) => {
    const endX = e.changedTouches[0].clientX;
    if (startX - endX > 50) {
      nextSlide();
    } else if (endX - startX > 50) {
      prevSlide();
    }
    startAutoPlay();
  }, { passive: true });

  window.addEventListener("resize", () => {
    if (currentIndex > getMaxIndex()) {
      currentIndex = getMaxIndex();
    }
    createDots();
    updateSlider();
  });

  createDots();
  updateSlider();
  startAutoPlay();
});
/* HOME SECTION 5 REVIEWS END */

/* HOME SECTION 8 FAQ START */
document.addEventListener("DOMContentLoaded", function () {
  const faqItems = document.querySelectorAll(".faq-item");

  faqItems.forEach((item) => {
    const questionBtn = item.querySelector(".faq-question-btn");
    const collapse = item.querySelector(".faq-answer-collapse");

    questionBtn.addEventListener("click", () => {
      const isActive = item.classList.contains("active");

      // Optional: Close other open FAQs for a clean accordion effect
      faqItems.forEach((otherItem) => {
        if (otherItem !== item) {
          otherItem.classList.remove("active");
          const otherCollapse = otherItem.querySelector(".faq-answer-collapse");
          if (otherCollapse) otherCollapse.classList.remove("show");
        }
      });

      // Toggle current FAQ
      if (isActive) {
        item.classList.remove("active");
        collapse.classList.remove("show");
      } else {
        item.classList.add("active");
        collapse.classList.add("show");
      }
    });
  });
});
/* HOME SECTION 8 FAQ END */

// SMOOTH SCROLL FOR BACK-TO-TOP BUTTON START
document.addEventListener("DOMContentLoaded", function () {
  const backToTopBtn = document.getElementById("footerBackToTop");
  if (backToTopBtn) {
    backToTopBtn.addEventListener("click", function () {
      window.scrollTo({
        top: 0,
        behavior: "smooth"
      });
    });
  }
});
// SMOOTH SCROLL FOR BACK-TO-TOP BUTTON END